B="BK-741"
C=[
("S09",2143,2147,"المحقق يعتمد على ملاحظته الأولى قبل التقارير",
 "ينبه الكتاب إلى أن أهم المعلومات في حادث إطلاق نار تأتي من معاينة المحقق نفسه للمكان والمصاب والملابس، وأن تقارير الخبراء تفيد بقدر جودة الفحص الأولي. فالفحص المهمل لا يعوضه خبير لاحقاً.",
 "اجعل ملاحظتك الأولى كاملة ومكتوبة: ماذا رأيت، أين، متى، قبل أن تقرأ تحليلاً من أحد.",
 "الملاحظة الأولى ليست حكماً نهائياً ويجب أن تُراجع بنتائج المختبر.",
 "","16-18","safe","scene_documentation",["KO-FC-04-026","KO-RS-06-004"],["ملاحظة أولية","معاينة"]),
("S09",2103,2117,"المسافة تُقدَّر بالتجربة المقارنة لا بأرقام جاهزة",
 "تتغير علامات الإصابة من القرب الشديد إلى البعد، لكن الكتاب نفسه يحذر من أن الأرقام الشائعة تتأثر بنوع السلاح والذخيرة ولا تصلح كقاعدة مطلقة. والأفضل مقارنة الأثر بتجارب تُجرى بالسلاح والذخيرة المضبوطين.",
 "اقبل من تقرير عبارة «من مسافة قريبة/متوسطة/بعيدة» مع بيان أساس المقارنة، واحذر من جدول يُعطي رقماً لكل حالة.",
 "تقدير المسافة نطاق تقريبي، ولا يحدد وضع الأشخاص وحده. (لا تحتوي المنصة أي أرقام أو أبعاد.)",
 "كل مسافة لها علامة ثابتة.","18+","sensitive","lab_limits",["KO-FC-04-016","KO-FC-04-031"],["تقدير المسافة","تجربة مقارنة"]),
("S09",2148,2152,"جرح الدخول وجرح الخروج: الحجم وحده دليل ضعيف",
 "يتغير حجم الجرحين بحسب المسافة والسرعة وما اصطدمت به الرصاصة، ولذلك لا يكفي الحجم للحكم. تفيد علامات إضافية مثل اتجاه حواف الجلد واتجاه ألياف الملابس والعظم.",
 "عند تحديد اتجاه الإصابة، اجمع أكثر من علامة (الجلد، الملابس، العظم) قبل أن ترسم اتجاه الإطلاق.",
 "قد تتشابه العلامات بعد الارتطام بعظم أو اختلاط الأنسجة، فيبقى الحكم احتمالياً.",
 "الجرح الأصغر هو دائماً جرح الدخول.","18+","sensitive","lab_limits",["KO-FC-04-016","KO-RS-06-004"],["جرح دخول","جرح خروج"]),
("S09",2147,2147,"اتجاه الطلق يُستنتج من مسار الجرح وآثار الارتطام",
 "يمكن تقدير اتجاه إطلاق النار من اتجاه الجرح في الجسد ومن آثار الارتطام في الجدران والأشياء القريبة، فتتشكل خطوط تقاطع تساعد في تحديد موضع المطلق. هذا يعمل كالمثلث: خطان من مصدرين يعطيان نقطة.",
 "ارسم على مخطط المكان خطاً من كل أثر، وانظر إلى أين تتقاطع الخطوط، واحذر من الارتداد.",
 "الارتداد وحركة الضحية أثناء الإطلاق قد تغيّر الخط، فتبقى النتيجة تقريبية.",
 "","18+","conceptual","scene_documentation",["KO-FC-04-026","KO-RS-06-016"],["مسار","تثليث"]),
("S09",2186,2188,"عدد الإصابات وموضعها وموضع الأداة قرائن لا قاعدة",
 "يقرر الكتاب قواعد عامة عن عدد الإصابات وموضعها وموضع السلاح، ثم يذكر استثناءات لها. فالقاعدة العامة تساعد في ترتيب الفرضيات، لكن الاستثناءات تمنع الحكم الآلي.",
 "اكتب القاعدة والاستثناء معاً: «الغالب كذا، لكن كذا ممكن» لتتجنب الاستنتاج الآلي.",
 "قواعد «الغالب» لا تحمي من الخطأ في الحالة الفردية.",
 "","18+","sensitive","reporting",["KO-RS-06-010","KO-RS-06-001"],["معدل أساسي","استثناء"]),
("S09",2178,2180,"رسالة الوداع تحتاج إثبات صاحبها",
 "قد توجد رسالة تُنسب إلى المتوفى، لكنها لا تعتمد قبل التحقق من أنها بخطه، لأن من يرتب مشهداً مضللاً قد يكتب رسالة. وتُفحص حالة الباب والنوافذ والمفتاح داخل القفل كذلك.",
 "اطلب فحص الخط ومقارنته بعينات معروفة، وتحقق من وقت الكتابة والورق والحبر قبل أن تعتمد الرسالة.",
 "مقارنة الخط لها حدود وتحتاج عينات كافية، ولا تعطي يقيناً مطلقاً.",
 "الرسالة المكتوبة تحسم الأمر.","16-18","sensitive","evidence_handling",["KO-FC-04-017","KO-FC-04B-004"],["مقارنة الخط","رسالة منسوبة"]),
("S09",2188,2188,"وضع السلاح في يد المتوفى لا يصنع قبضة حقيقية",
 "يذكر الكتاب أن قبضة اليد الشديدة على الأداة قد تدل على أن صاحبها كان حياً ممسكاً بها وقت الوفاة، لأن من يضع الأداة في يد غيره لا يستطيع صنع القبضة الحقيقية. لكنه يحذر من أن غياب الأداة لا يعني شيئاً قاطعاً.",
 "عند وصف يد تمسك شيئاً، اسأل: هل هو إمساك أم وضع؟ وانتبه إلى التيبس وحالته قبل أن تستنتج.",
 "هذه حالات نادرة، ولا يجوز تعميمها، وتحتاج تقييماً طبياً.",
 "","18+","sensitive","scene_documentation",["KO-RS-06-004"],["قبضة","وضع الأداة"]),
("S09",2192,2194,"رصاصة واحدة قد تُحدث عدة جروح",
 "قد تمر رصاصة واحدة عبر أكثر من جزء في الجسد بحسب وضعية الشخص وقت الإصابة، وقد تكتفي أحياناً بخدش على الجلد يشبه جرحاً سطحياً. ولذلك لا يساوي عدد الجروح عدد الطلقات تلقائياً.",
 "قبل أن تقول «أُطلقت ثلاث رصاصات» اسأل: هل يمكن أن تفسر رصاصة واحدة بعض هذه الجروح بحسب وضع الجسد؟",
 "الجواب النهائي يحتاج جمع المقذوفات والأظرف ومسارات الجروح.",
 "عدد الجروح يساوي عدد الرصاصات.","18+","conceptual","reporting",["KO-RS-06-016","KO-RS-06-007"],["مسار الجرح","عدد الطلقات"]),
("S09",2197,2198,"خرافة: الرصاصة المحمية تحرق الملابس",
 "كثيراً ما يُظن أن المقذوف يصل ساخناً بما يكفي لحرق القماش، لكن الحرارة التي يكتسبها لا تكفي لذلك. ويُنسب الاسوداد حول الجرح أحياناً إلى الاحتراق بينما هو أثر رض أو أوساخ علقت بالمقذوف.",
 "عندما يُنسب أثر إلى سبب شائع بين الناس، اطلب دليلاً يفرق بينه وبين سبب بديل.",
 "الأثر الأسود حول جرح قد يأتي من أكثر من مصدر، ويحتاج فحصاً.",
 "الرصاصة تحرق ما تلمس.","16-18","conceptual","lab_limits",["KO-FC-04-032","KO-RS-06-005"],["خرافة","أثر أسود"]),
("S09",2199,2209,"إصابة نارية مدّعاة ومفتعلة: سجّل الرواية فوراً",
 "ينبه الكتاب إلى أن من يفتعل إصابة غالباً يطلق على ملابسه فقط أو يصيب نفسه في موضع غير خطر، وأن الأهم تدوين روايته كاملة وبتفاصيلها عند أول لقاء قبل أن يعدّلها. ثم تقارن الرواية بالملابس والجروح والمكان.",
 "اكتب الرواية بحروفها في المرة الأولى، ثم قارن: وضع الواقف، المسافة المزعومة، مكان الثقوب في الملابس، هل تتفق جميعاً؟",
 "الاختلاف قد ينتج عن صدمة وليس عن كذب، فلا يُبنى عليه اتهام وحده.",
 "","16-18","safe","witness_reliability",["KO-RS-05-014","KO-RS-06-020"],["رواية أولى","مطابقة الرواية"]),
("S09",2209,2209,"ثقب الزجاج: من الداخل أم من الخارج؟",
 "حواف الثقب في الزجاج تختلف بين جهة الدخول وجهة الخروج، ولذلك يمكن معرفة اتجاه ما اخترقه حتى مع عدم وجود شاهد. هذا مثال على قراءة اتجاه القوة من شكل الكسر.",
 "عند فحص زجاج مكسور، صف شكل الحواف في الجهتين بدل الاكتفاء بقول «كُسر».",
 "قد يتكسر الزجاج بتصادمات متتابعة فتختلط الدلالات.",
 "","18+","safe","scene_documentation",["KO-FC-04-018","KO-RS-06-016"],["اتجاه الكسر","زجاج"]),
("S09",2210,2212,"التعرف على المطلق في وميض قصير: شهادة هشّة",
 "يقرر الكتاب أن التعرف على شخص على ضوء إطلاق قصير ممكن فقط إذا كان معروفاً للضحية، أما الغريب فلا تُعطي الشهادة تفاصيل مفيدة. فالضوء قصير والمسافة والظلام وبصر الشاهد عوامل مؤثرة.",
 "قدّر ظروف الرؤية: مدة الضوء، المسافة، الإضاءة، معرفة سابقة؟ ثم أعطِ الوزن لشهادة التعرف بحسب ذلك.",
 "حتى المعرفة السابقة لا تكفي وحدها، فقد يخطئ الشاهد المتأثر.",
 "من رأى الوميض يعرف من أطلق.","16-18","safe","witness_reliability",["KO-RS-05-008","KO-FC-04-027"],["ظروف الرؤية","تعرف سريع"]),
("S09",2216,2218,"ابدأ بالتصوير والرسم قبل نقل أي أثر",
 "يوصي الكتاب بتصوير كل أثر في مكانه من قرب ومن بعيد مع بيان علاقته بما حوله، وبرسم كروكي للمشهد، وإعادة أي أثر نُقل إلى موضعه قبل التصوير. فالتوثيق يسبق الرفع.",
 "طبّق ترتيب «صورة بعيدة، صورة متوسطة، صورة قريبة بمقياس، ثم رسم، ثم رفع» على أي أثر.",
 "التصوير لا يغني عن الرفع الصحيح ولا يعوّض الأثر الضائع.",
 "","13-15","safe","scene_documentation",["KO-FC-04-026"],["كروكي","تصوير متدرج"]),
("S09",2222,2229,"مكان الظرف الفارغ ومكان المقذوف يكشفان نقل الجثة",
 "يفيد موضع الظرف الفارغ في تقدير مكان وقوف المطلق، ويفيد موضع المقذوف في تحديد موضع الحادث لأن المقذوف يسير في خط مستقيم ما لم يصطدم. فإذا لم يتفق موضع الجثة مع خط مسار المقذوف، قد تكون الجثة نُقلت.",
 "اسأل عن كل أثر: هل يمكن أن يكون الفاعل حرّكه؟ فالظرف أسهل في التحريك من المقذوف.",
 "ارتداد المقذوف وارتطامه بأشياء قد يغيّران الخط، فلا يُحكم من أثر واحد.",
 "","18+","conceptual","scene_documentation",["KO-FC-04-026","KO-RS-06-016"],["نقل الجثة","موضع الأثر"]),
("S09",2229,2229,"كل ظرف وكل مقذوف في حرز مستقل وموضع مسجل",
 "عند وجود أكثر من ظرف أو مقذوف يُسجل موضع كل واحد وبعده عن الجثة ويصوّر ويحفظ في حرز مستقل ليُعرف دور كل طلقة وعدد الأسلحة المحتملة. الخلط بين الآثار يضيّع هذه الدلالة.",
 "رقّم كل أثر على المخطط وفي الحرز بالرقم نفسه، حتى تستطيع أن تتتبع كل أثر في التقرير.",
 "الحرز المشترك أو المرقم خطأً يفسد قيمة الدليل في المحكمة.",
 "","16-18","safe","evidence_handling",["KO-FC-04-026","KO-FC-04B-002"],["حرز مستقل","ترقيم الآثار"]),
("S09",2257,2258,"قد يحرّك الجاني آثار الإطلاق ليضلل",
 "يوسّع الباحث دائرة بحثه عن الظرف الفارغ لأنه قد يرتد أو يصطدم بما يبعده، وقد يجمع الجاني الأظرف أو يغيّر مواضعها لتضليل المحقق. لذلك تقارن الأظرف مع نوع السلاح والمسافات للكشف عن التحريك.",
 "عند ظهور أثر في موضع «مثالي»، اسأل: هل يمكن أن يكون وُضع؟ وما الأدلة على موضعه الأصلي؟",
 "لا يمكن الجزم بالتحريك دون قرائن مكانية.",
 "","18+","conceptual","scene_documentation",["KO-RS-06-020","KO-FC-04-026"],["تضليل","تحريك الأثر"]),
("S09",2241,2246,"آثار الإطلاق على اليد: قرينة تحتاج حذراً",
 "يمكن في بعض الحالات الكشف عن آثار دخان وجسيمات على يد من أطلق السلاح، وتفيد في أسئلة كالانتحار أو وضع السلاح في يد المتوفى. لكن وجود الأثر لا يدل وحده على من أطلق، فقد يلوّث الشخص بالقرب من السلاح.",
 "اطلب جمع عينات اليد مبكراً وقبل الغسل، ولا تُفسَّر النتيجة إلا مع موضع الشخص وقت الحادث.",
 "قد تنتقل الجسيمات بين الأسطح، وقد تزول بالغسل والاحتكاك، فالنتيجة السلبية لا تنفي.",
 "ظهور بارود على اليد يثبت الإطلاق.","18+","conceptual","lab_limits",["KO-FC-04-007","KO-FC-04-019"],["انتقال الأثر","عينة اليد"]),
("S09",2316,2324,"نتائج فحوص النترات قد تكون إيجابية لأسباب يومية",
 "ينبه الكتاب إلى أن فحص النترات على اليد قد يعطي نتيجة إيجابية بسبب مواد نترات تدخل في أعمال الحياة اليومية، فلا يُعتد بها قبل استبعاد هذه المصادر. هذا مثال على الإيجابية الكاذبة.",
 "اسأل عن مهنة الشخص ومحيطه قبل تفسير أي فحص كيميائي سريع يتأثر بمواد شائعة.",
 "الفحص التمهيدي لا يميّز مصدر المادة، وتبقى الحاجة للتأكيد.",
 "نتيجة إيجابية على اليد تعني أنه أطلق النار.","18+","conceptual","lab_limits",["KO-FC-04-019","KO-FC-04-004"],["إيجابية كاذبة","تلوث يومي"]),
("S09",2279,2285,"أربعة أسئلة يطرحها المحقق على فحص السلاح",
 "يلخص الكتاب أسئلة الفحص: هل الطلقة من هذا السلاح؟ ما المسافة؟ متى استُعمل؟ من استعمله؟ وكل سؤال له وسائله ومحدداته. فالسؤال الأول يعتمد على المقارنة المجهرية، والثاني على التجربة، والثالث والرابع على آثار معرضة للزوال.",
 "حين يصلك تقرير سلاح، اكتب الأسئلة الأربعة وضع تحت كل منها ما يجيب عنه التقرير فعلاً وما لا يجيب.",
 "قد لا يجيب الفحص عن السؤال كله، وبعض الأسئلة تبقى مفتوحة.",
 "","16-18","conceptual","reporting",["KO-FC-04-016","KO-FC-04-031"],["أسئلة الفحص","تقرير سلاح"]),
("S09",2290,2294,"مضاهاة الخطوط المجهرية: وصف قديم بثقة عالية",
 "يصف الكتاب مقارنة آثار المقذوف والظرف بالمجهر المقارن ويقول إن التماثل التام يعد دليلاً قاطعاً. أما الأدبيات الحديثة فتعتبر هذا النوع من المقارنة موضع خلاف وتطلب التعبير عنه بحدود وبتقدير خطأ.",
 "عندما تقرأ عبارة «مطابقة قاطعة»، اسأل: ما معدل الخطأ المقاس؟ ومن راجع؟ وما نوع الصياغة المقبولة اليوم؟",
 "الرأي الحديث أكثر تحفظاً من الصياغة القديمة، وأن لغة «القطع» غير مناسبة بلا دعم إحصائي.",
 "المجهر يربط كل رصاصة بسلاح واحد بلا خطأ.","18+","conceptual","lab_limits",["KO-FC-04-016","KO-FC-04-004","KO-FC-04B-005"],["مجهر مقارن","معدل الخطأ"]),
("S09",2301,2306,"رائحة السلاح تدل على حداثة الاستعمال لمدة قصيرة فقط",
 "قد تدل رائحة الاحتراق في سلاح مضبوط على استعمال حديث، لكنها تزول بالتهوية أو الماء أو مسح السلاح. لذلك يحرَّز السلاح بسرعة، ويُعامل التقدير كمدى قصير لا كموعد.",
 "اكتب: «يوجد/لا يوجد رائحة» مع وصف حفظ السلاح، ولا تحوّلها إلى ساعة محددة.",
 "قد يغيب الأثر في سلاح استُعمل حديثاً، وقد يوجد في سلاح قديم قريب من مصدر دخان.",
 "","18+","conceptual","timing",["KO-FC-04-021"],["حداثة الاستعمال","حفظ الأثر"]),
("S09",2327,2362,"جثة مجهولة: تحديد الهوية ثم الدافع ثم الفاعل",
 "في قضية جثة مدفونة، جرى حصر حالات الغياب وعرض صور الجثة والملابس، ثم أمكن التعرف على الضحية عبر أقاربه، ثم ظهر الخلاف العائلي والدافع. وفي النهاية عُثر على متعلقات الضحية مع الفاعل، فتكاملت الأدلة.",
 "رتّب أسئلتك: من هو؟ متى اختفى؟ من آخر من رآه؟ وما الذي ربط الأشخاص بالمكان؟ فتحديد الهوية يفتح بقية الأسئلة.",
 "عثور متعلقات الضحية مع شخص يحتاج تفسيراً وتحققاً قبل أن يُعدّ دليل فعل.",
 "","16-18","safe","reporting",["KO-RS-05-005","KO-RS-06-006"],["تحديد هوية","حصر الغياب"]),
("S09",2391,2424,"الاتهام الأول من ذوي الضحية لا يكفي",
 "في قضية رُجّح فيها شخص بالاتهام من الزوجة في أول بلاغ، بيّنت التحريات أن للأمر خلفية أخرى تتعلق بأطراف من الأسرة. فاتهام صاحب المصلحة أو المنفعل هو خيط للتحقق وليس نتيجة.",
 "اكتب الاتهام الأول كفرضية رقم واحد، وأضف فرضيات بديلة، ثم اختبر كلاً منها بالمصادر المستقلة.",
 "قد يكون الاتهام الأول صحيحاً أحياناً، والمهم عدم الاكتفاء به.",
 "من قال أول اسم فهو محق.","16-18","safe","witness_reliability",["KO-RS-06-006","KO-RS-05-009"],["اتهام أول","فرضيات بديلة"]),
("S10",2434,2451,"تأثير المادة السامة يتغير بسبب عوامل كثيرة",
 "تتأثر سرعة وشدة تأثير أي مادة سامة بالكمية وشكلها وطريقة وصولها وامتلاء المعدة والعمر والحالة الصحية والاستعداد الفردي وتعوّد الجسم. لهذا لا يوجد رقم واحد للجميع.",
 "عند قراءة قصة تسمم، اسأل عن هذه العوامل قبل أن تقول إن الكمية كافية أو غير كافية.",
 "هذا مفهوم عام للتحليل ولا يقدم جرعات أو طرقاً.",
 "الجرعة الصغيرة لا تؤذي أحداً.","16-18","conceptual","lab_limits",["KO-FC-04-020","KO-FC-04-022"],["الاستعداد الفردي","الجرعة والاستجابة"]),
("S10",2452,2455,"ما يُعثر عليه في الجثة بقايا لا الجرعة الأصلية",
 "يتحول جزء من المادة في الجسم ويُطرح جزء، فالموجود في الأعضاء بعد الوفاة يمثل ما تبقى فقط، ولا توجد وسيلة لمعرفة الكمية الأصلية. لذلك لا نقول «تناول كذا» بمجرد تقدير الموجود.",
 "تعلّم الفرق بين «اكتشاف مادة» و«إثبات أنها السبب» و«معرفة كم أُعطي». هذه ثلاثة أسئلة مختلفة.",
 "الاكتشاف ليس سببية، والكمية الأصلية مجهولة.",
 "وجود المادة يعني أنها سبب الوفاة.","16-18","safe","lab_limits",["KO-FC-04-020","KO-FC-04-019"],["اكتشاف مقابل سببية","بقايا"]),
("S10",2459,2459,"إثبات التسمم من خمسة خطوط معاً",
 "يقوم إثبات التسمم على الأعراض في الحياة والتشريح والتحليل الكيميائي والمجهري والتجارب وظروف القضية كالدافع والحصول على المادة. لا يكفي خط واحد منها.",
 "اجمع الخطوط الخمسة في جدول وانظر أيها قوي وأيها ناقص قبل أن تقدم استنتاجاً.",
 "تضارب الخطوط يعني أن الاستنتاج غير جاهز.",
 "","16-18","safe","reporting",["KO-RS-05-004","KO-FC-04-001"],["تلاقي الأدلة","أعراض وتحليل"]),
("S10",2461,2464,"تكرار الأعراض بين أكلة طعام واحد يرجّح مصدراً مشتركاً",
 "إذا ظهرت أعراض فجأة على عدة أشخاص أكلوا الطعام نفسه، فهذا يرجّح مصدراً مشتركاً، ويوجه التحقيق إلى الطعام بدل افتراض أن كل شخص مصاب بمرض منفصل. لكن الكتاب يحذر أن أمراضاً طبيعية تعطي صورة تشبه التسمم.",
 "ارسم من أكل ماذا ومتى وظهرت عليه الأعراض، فالرسم يبين المصدر المحتمل بوضوح.",
 "مصدر مشترك لا يعني تسميماً متعمداً؛ فقد يكون فساداً غذائياً.",
 "","13-15","safe","scene_documentation",["KO-RS-05-005","KO-RS-06-017"],["مصدر مشترك","جدول الوجبات"]),
("S10",2906,2926,"التسمم الغذائي: الأعراض تتأخر والشك يسبق الدليل",
 "الطعام الفاسد في الأجواء الحارة قد يسبب أعراضاً شديدة، وبعض الأعراض تتأخر ساعات، والناس يميلون إلى اتهام من أعد الطعام. يلاحظ الكتاب أن الشبهة الجنائية تكثر في مواسم معينة دون أن تكون هناك حقيقة وراءها.",
 "قبل أن تتهم أحداً بدس مادة، افحص حفظ الطعام وتوقيته ومن تناوله، وانتظر نتيجة المختبر.",
 "التفسير البريء يجب أن يُستبعد بالدليل لا بالافتراض.",
 "كل مرض بعد طعام يعني تسميماً.","13-15","safe","witness_reliability",["KO-RS-06-004","KO-RS-06-015"],["فساد غذائي","اتهام متسرع"]),
("S10",2916,2916,"لدغ الحيوان وسمّه: فحص ظاهري يكفي لاستبعاد الجريمة غالباً",
 "في حالات اللدغ والعض من الزواحف والحشرات يكتفي الفحص الظاهري غالباً بنفي الاعتبار الجنائي، دون تشريح كامل. فالنهج يتدرج بحسب ما يشير إليه المشهد.",
 "اكتب سؤالاً: ما أقل فحص يكفي لاستبعاد الفعل الجنائي هنا؟ وما الذي يستدعي التوسع؟",
 "إذا ظهرت علامات غير متسقة مع اللدغ، يتوسع الفحص.",
 "","16-18","safe","reporting",["KO-RS-05-013","KO-FC-04-022"],["استبعاد","نطاق الفحص"]),
]
